<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        InputStream inStream = System.in;
        BufferedReader reader = new BufferedReader(new InputStreamReader(inStream));
        int n = Integer.parseInt(reader.readLine());
        String s = reader.readLine().replaceAll("_+", " ");
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '(') {
                sb.append(" ( ");
            } else if (c == ')') {
                sb.append(" ) ");
            } else {
                sb.append(c);
            }
        }
        String[] tokens = sb.toString().split(" +");
        boolean inParen = false;
        int maxLen = 0, countParen = 0;
        for (String token : tokens) {
            if (token.contains("(")) {
                inParen = true;
            } else if (token.contains(")")) {
                inParen = false;
            } else if (!token.contains("(") && !token.contains(")")) {
                if (inParen) {
                    countParen++;
                } else {
                    maxLen = Math.max(maxLen, token.length());
                }
            }
        }
        System.out.println(maxLen + " " + countParen);
    }
}
